<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\StorePengajuanPerubahanRequest; use App\Services\PengajuanPerubahanService; use Illuminate\Http\Request;
class PengajuanPerubahanController extends Controller { public function __construct(private PengajuanPerubahanService $service){} public function store(StorePengajuanPerubahanRequest $r){$u=$r->user();$s=$u->siswa()->firstOrFail();$d=$r->validated();$p=$this->service->ajukan((int)$s->id_siswa,(int)$d['id_periode_update'],$d['alasan'],$d['detail']);return response()->json($p,201);} public function keputusan(Request $r,int $id){abort_unless($r->user()->hasPermission('siswa.update.approve'),403);$d=$r->validate(['keputusan'=>'required|in:disetujui,ditolak,perlu_perbaikan','catatan'=>'nullable|string|max:2000']);$this->service->putuskan($id,(int)$r->user()->id_pengguna,$d['keputusan'],$d['catatan']??null);return response()->json(['message'=>'Keputusan tersimpan']);} }
